import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`restaurant-supplier-finder`,heroTitle:`Find better suppliers for your restaurant in minutes`,heroSubtitle:`Perplexity Computer analyzes your menu, researches local and wholesale suppliers, and builds a sourcing plan with pricing — automatically.`,inputUrlCta:`Find my suppliers`,inputUrlPlaceholder:`yourrestaurant.com`,inputUrlPrefill:`Go to {url} and perform a complete restaurant supplier analysis. 1) Extract the full menu, identifying all key ingredients, proteins, produce, dairy, dry goods, beverages, and specialty items the restaurant needs to source. 2) Research and identify the top suppliers — local farms, wholesale distributors, broadline distributors, and specialty vendors — available in the restaurant's geographic area. 3) For each major ingredient category, compare at least 3 supplier options with estimated pricing, minimum order quantities, delivery schedules, and any notable quality or sourcing certifications (organic, sustainable, etc.). 4) Flag any specialty or hard-to-source ingredients and recommend niche suppliers for those items. 5) Identify potential cost savings by comparing current typical restaurant pricing against alternative suppliers. 6) Deliver a prioritized supplier shortlist organized by category, with contact information, estimated monthly spend, and a recommended action plan for switching or diversifying suppliers.`,heroOverlaySteps:[`Analyzing your menu for ingredients and sourcing needs`,`Researching wholesale, local, and specialty suppliers in your area`,`Comparing pricing, delivery schedules, and minimum orders`,`Supplier shortlist with pricing and contact details — ready to review`],generatingSteps:[`Visiting {url} to extract your menu, ingredients, and location`,`Designing an agent to research and compare suppliers across every ingredient category`,`Configuring pricing comparison, delivery analysis, and quality certification checks`,`Setting up your supplier shortlist with contact info and cost-saving recommendations`],featureSectionTitle:`From menu to supplier shortlist`,featureCardTitles:[`Connects to your restaurant stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Notion, Airtable, QuickBooks — Computer organizes your supplier data and cost analysis in the tools you already use.`,`Supplier shortlists by category. Pricing comparisons with estimated savings. Delivery schedule breakdowns. Contact details and a step-by-step switching plan.`],capabilitySectionTitle:`Your sourcing manager, on autopilot`,capabilitySectionSubtitle:`Paste your restaurant URL, step away, come back to a complete supplier plan.`,capabilityCards:[{title:`Menu Analysis`,description:`Computer can parse your full menu — proteins, produce, dairy, dry goods, beverages, and specialty items — to build a complete ingredient sourcing list.`},{title:`Supplier Research`,description:`Computer can search local farms, broadline distributors, and specialty vendors in your area — and surface options you didn't know existed.`},{title:`Price Comparison`,description:`Computer can compare pricing, minimum orders, and delivery terms across multiple suppliers per category — and flag where you're overpaying.`},{title:`Connect Your Tools`,description:`Computer can push supplier lists, pricing data, and cost projections into Google Sheets, Airtable, Notion, and QuickBooks — keeping your operations in sync.`},{title:`Remember & Learn`,description:`Computer can remember your preferred suppliers, past quotes, and seasonal menu changes — so every sourcing run builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can track supplier pricing shifts and availability changes — and alert you when it's time to renegotiate or switch vendors.`}]});export{t as default};
